<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan Bulanan</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/attendance.css"><link rel="stylesheet" href="/assets/css/journals.css"></head><body><main class="attendance-page"><header><a href="/dashboard">← Dashboard</a><div><span>Laporan</span><h1>Laporan jurnal bulanan</h1><p>Ringkasan jurnal dan kehadiran berdasarkan periode.</p></div></header><form id="report-filter" class="toolbar"><select name="month" aria-label="Bulan"><?php foreach(['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'] as $i=>$name):?><option value="<?= $i+1 ?>" <?= $i+1==date('n')?'selected':'' ?>><?= $name ?></option><?php endforeach?></select><input name="year" type="number" min="2020" max="2100" value="<?= date('Y') ?>" aria-label="Tahun"><select name="status"><option value="">Semua status</option><option>DRAFT</option><option>FINAL</option><option>AMENDED</option></select><button>Tampilkan</button></form><div class="report-actions"><a id="excel-link" href="#">Unduh Excel</a><a id="pdf-link" href="#">Unduh PDF</a></div><section id="report-summary" class="summary"></section><div class="report-table"><table><thead><tr><th>Tanggal</th><th>Kelas</th><th>Mapel</th><th>Pokok bahasan</th><th>H</th><th>S</th><th>I</th><th>A</th><th>Status</th></tr></thead><tbody id="report-rows"><tr><td colspan="9">Memuat laporan…</td></tr></tbody></table></div></main><script type="module" src="/assets/js/report-monthly.js"></script></body></html>
